/* Halcyon Threshold - Minimal, readable design */

:root {
    --color-bg: #fafaf9;
    --color-text: #1c1917;
    --color-text-muted: #57534e;
    --color-accent: #0369a1;
    --color-accent-hover: #0284c7;
    --color-border: #e7e5e4;
    --font-serif: Georgia, 'Times New Roman', serif;
    --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --max-width: 680px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-serif);
    font-size: 18px;
    line-height: 1.7;
    color: var(--color-text);
    background: var(--color-bg);
}

/* Navigation */
header {
    border-bottom: 1px solid var(--color-border);
    padding: 1rem 2rem;
}

nav {
    max-width: var(--max-width);
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-family: var(--font-sans);
    font-weight: 600;
    font-size: 1.1rem;
    color: var(--color-text);
    text-decoration: none;
}

.nav-links {
    display: flex;
    gap: 1.5rem;
}

.nav-links a {
    font-family: var(--font-sans);
    font-size: 0.9rem;
    color: var(--color-text-muted);
    text-decoration: none;
}

.nav-links a:hover {
    color: var(--color-accent);
}

/* Main content */
main {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 3rem 2rem;
}

section {
    margin-bottom: 3rem;
}

/* Hero */
.hero {
    text-align: center;
    padding: 2rem 0 3rem;
    border-bottom: 1px solid var(--color-border);
    margin-bottom: 3rem;
}

.hero h1 {
    font-family: var(--font-sans);
    font-size: 2.5rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.tagline {
    font-size: 1.15rem;
    color: var(--color-text-muted);
    font-style: italic;
}

/* Content sections */
h2 {
    font-family: var(--font-sans);
    font-size: 1.3rem;
    font-weight: 600;
    margin-bottom: 1rem;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin: 1rem 0 1rem 1.5rem;
}

li {
    margin-bottom: 0.5rem;
}

a {
    color: var(--color-accent);
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 2px;
}

a:hover {
    color: var(--color-accent-hover);
}

strong {
    font-weight: 600;
}

em {
    font-style: italic;
}

/* Footer */
footer {
    border-top: 1px solid var(--color-border);
    padding: 2rem;
    text-align: center;
    font-size: 0.9rem;
    color: var(--color-text-muted);
}

footer a {
    color: var(--color-text-muted);
}

/* Responsive */
@media (max-width: 600px) {
    body {
        font-size: 16px;
    }

    .hero h1 {
        font-size: 2rem;
    }

    header {
        padding: 1rem;
    }

    main {
        padding: 2rem 1rem;
    }
}

